        arcoDeAnel(formas, x + largura - r, y + r, r - e, r, 270f, 90f, cor);
        arcoDeAnel(formas, x + largura - r, y + altura - r, r - e, r, 0f, 90f, cor);
        arcoDeAnel(formas, x + r, y + altura - r, r - e, r, 90f, 90f, cor);
