package wumpusworld.grafico;

import com.badlogic.gdx.graphics.Color;
import com.badlogic.gdx.graphics.glutils.ShapeRenderer;
import com.badlogic.gdx.math.MathUtils;

import wumpusworld.nucleo.Direcao;

/**
 * Desenho vetorial dos elementos do mundo.
 *
 * <p>Nenhum ícone vem de arquivo de imagem: todos são compostos por círculos,
 * triângulos, anéis e polígonos calculados a partir do centro e do tamanho da
 * casa. Isso mantém o projeto sem dependência de recursos externos, deixa as
 * figuras nítidas em qualquer escala e permite animá-las (pulsação, oscilação
 * e brilho) apenas variando o tempo.</p>
 *
 * <p>Todos os métodos esperam o {@link ShapeRenderer} já aberto no modo
 * {@code Filled}, com mistura de transparência habilitada.</p>
 */
public final class Icones {

    private Icones() {
    }

    /** Ângulo, em graus, correspondente a cada direção da matriz. */
    private static float anguloDe(Direcao direcao) {
        return switch (direcao) {
            case DIREITA -> 0f;
            case CIMA -> 90f;
            case ESQUERDA -> 180f;
            case BAIXO -> 270f;
        };
    }

    // -----------------------------------------------------------------------
    //  Agente
    // -----------------------------------------------------------------------

    /**
     * Explorador visto de cima: um capacete com lanterna apontando para a
     * direção do último movimento.
     *
     * @param lado     lado da casa, usado como referência de tamanho
     * @param olhar    direção para onde o agente está voltado
     * @param vivo     define se o ícone é o explorador ou a caveira
     * @param comOuro  acrescenta o anel dourado do tesouro recolhido
     */
    public static void agente(ShapeRenderer formas, float centroX, float centroY,
            float lado, Direcao olhar, boolean vivo, boolean comOuro, float tempo) {

        if (!vivo) {
            caveira(formas, centroX, centroY, lado);
            return;
        }

        float raio = lado * 0.22f;
        float angulo = anguloDe(olhar) * MathUtils.degreesToRadians;
        float cosseno = MathUtils.cos(angulo);
        float seno = MathUtils.sin(angulo);

        // Aura respirando ao redor do agente.
        float pulso = Desenho.pulsar(tempo, 3.2f);
        for (int camada = 3; camada >= 1; camada--) {
            // O maior raio fica em 1,81 × raio, ou seja, dentro da própria casa.
            float raioAura = raio * (1.15f + camada * 0.22f + pulso * 0.10f);
            formas.setColor(Paleta.comAlfa(Paleta.AGENTE, 0.07f * camada));
            formas.circle(centroX, centroY, raioAura, 40);
        }

        // Feixe da lanterna, apontando para onde o agente decidiu ir.
        float alcance = raio * 2.05f;
        float meiaBase = raio * 1.05f;
        float pontaX = centroX + cosseno * alcance;
        float pontaY = centroY + seno * alcance;
        float perpendicularX = -seno * meiaBase;
        float perpendicularY = cosseno * meiaBase;
        formas.setColor(Paleta.comAlfa(Paleta.AGENTE_BRILHO, 0.12f + pulso * 0.05f));
        formas.triangle(centroX, centroY,
                pontaX + perpendicularX, pontaY + perpendicularY,
                pontaX - perpendicularX, pontaY - perpendicularY);

        // Corpo: aro externo, capacete e lanterna.
        formas.setColor(Paleta.AGENTE_ESCURO);
        formas.circle(centroX, centroY, raio * 1.16f, 36);
        formas.setColor(Paleta.AGENTE);
        formas.circle(centroX, centroY, raio * 0.94f, 36);

        formas.setColor(Paleta.comAlfa(Paleta.AGENTE_ESCURO, 0.55f));
        formas.circle(centroX - cosseno * raio * 0.22f,
                centroY - seno * raio * 0.22f, raio * 0.58f, 28);

        formas.setColor(Paleta.AGENTE_BRILHO);
        formas.circle(centroX + cosseno * raio * 0.40f,
                centroY + seno * raio * 0.40f, raio * 0.34f, 24);

        // Ponta triangular indicando o sentido do movimento.
        float distanciaDaPonta = raio * 1.52f;
        float meiaPonta = raio * 0.46f;
        float baseX = centroX + cosseno * raio * 1.02f;
        float baseY = centroY + seno * raio * 1.02f;
        formas.setColor(Paleta.AGENTE_BRILHO);
        formas.triangle(
                centroX + cosseno * distanciaDaPonta,
                centroY + seno * distanciaDaPonta,
                baseX - seno * meiaPonta, baseY + cosseno * meiaPonta,
                baseX + seno * meiaPonta, baseY - cosseno * meiaPonta);

        if (comOuro) {
            Desenho.anel(formas, centroX, centroY,
                    raio * 1.30f, raio * 1.52f,
                    Paleta.comAlfa(Paleta.OURO, 0.75f + pulso * 0.25f), 40);
        }
    }

    /** Marca da derrota: uma caveira simples no lugar do explorador. */
    public static void caveira(ShapeRenderer formas, float centroX, float centroY,
            float lado) {
        float raio = lado * 0.21f;

        formas.setColor(Paleta.comAlfa(Paleta.PERIGO, 0.16f));
        formas.circle(centroX, centroY, raio * 2.0f, 34);

        formas.setColor(Paleta.TEXTO);
        formas.circle(centroX, centroY + raio * 0.18f, raio, 32);
        formas.rect(centroX - raio * 0.52f, centroY - raio * 1.05f,
                raio * 1.04f, raio * 0.75f);

        formas.setColor(Paleta.POCO);
        formas.circle(centroX - raio * 0.40f, centroY + raio * 0.26f, raio * 0.30f, 20);
        formas.circle(centroX + raio * 0.40f, centroY + raio * 0.26f, raio * 0.30f, 20);
        formas.rect(centroX - raio * 0.12f, centroY - raio * 0.40f,
                raio * 0.24f, raio * 0.30f);

        formas.setColor(Paleta.PERIGO);
        formas.rect(centroX - raio * 0.44f, centroY - raio * 1.02f, raio * 0.12f, raio * 0.68f);
        formas.rect(centroX - raio * 0.06f, centroY - raio * 1.02f, raio * 0.12f, raio * 0.68f);
        formas.rect(centroX + raio * 0.32f, centroY - raio * 1.02f, raio * 0.12f, raio * 0.68f);
    }

    // -----------------------------------------------------------------------
    //  Poço
    // -----------------------------------------------------------------------

    /** Buraco escuro com profundidade sugerida por anéis concêntricos. */
    public static void poco(ShapeRenderer formas, float centroX, float centroY,
            float lado, float tempo) {
        float raio = lado * 0.32f;

        // Halo frio ao redor da boca do poço.
        formas.setColor(Paleta.comAlfa(Paleta.POCO_BORDA, 0.55f));
        formas.circle(centroX, centroY, raio * 1.14f, 44);

        Desenho.anel(formas, centroX, centroY, raio * 0.95f, raio * 1.08f,
                Paleta.comAlfa(Paleta.BORDA_FORTE, 0.9f), 44);

        int camadas = 8;
        for (int camada = 0; camada < camadas; camada++) {
            float fator = camada / (float) (camadas - 1);
            float raioDaCamada = raio * (1f - fator * 0.82f);
            formas.setColor(Paleta.misturar(Paleta.POCO_BORDA, Paleta.POCO, fator));
            formas.circle(centroX, centroY - fator * raio * 0.10f,
                    raioDaCamada, 40);
        }

        // Pequenas pedras soltas na borda, para quebrar a simetria.
        float giro = tempo * 0.35f;
        formas.setColor(Paleta.comAlfa(Paleta.BORDA_FORTE, 0.6f));
        for (int pedra = 0; pedra < 5; pedra++) {
            float angulo = giro + pedra * MathUtils.PI2 / 5f;
            formas.circle(
                    centroX + MathUtils.cos(angulo) * raio * 1.18f,
                    centroY + MathUtils.sin(angulo) * raio * 1.18f,
                    raio * 0.06f, 10);
        }
    }

    // -----------------------------------------------------------------------
    //  Wumpus
    // -----------------------------------------------------------------------

    /** Criatura roxa com chifres, olhos vermelhos e dentes. */
    public static void wumpus(ShapeRenderer formas, float centroX, float centroY,
            float lado, float tempo) {
        float raio = lado * 0.25f;
        float balanco = MathUtils.sin(tempo * 2.1f) * lado * 0.014f;
        float y = centroY + balanco;

        formas.setColor(Paleta.comAlfa(Paleta.WUMPUS, 0.14f));
        formas.circle(centroX, y, raio * 1.85f, 38);

        // Chifres.
        formas.setColor(Paleta.WUMPUS_ESCURO);
        formas.triangle(
                centroX - raio * 0.86f, y + raio * 0.42f,
                centroX - raio * 0.30f, y + raio * 0.66f,
                centroX - raio * 0.62f, y + raio * 1.34f);
        formas.triangle(
                centroX + raio * 0.86f, y + raio * 0.42f,
                centroX + raio * 0.30f, y + raio * 0.66f,
                centroX + raio * 0.62f, y + raio * 1.34f);

        // Corpo.
        formas.setColor(Paleta.WUMPUS_ESCURO);
        formas.circle(centroX, y, raio * 1.08f, 40);
        formas.setColor(Paleta.WUMPUS);
        formas.circle(centroX, y, raio * 0.94f, 40);

        // Boca com dentes.
        formas.setColor(Paleta.POCO);
        formas.arc(centroX, y - raio * 0.10f, raio * 0.62f, 196f, 148f, 24);

        formas.setColor(Paleta.TEXTO);
        for (int dente = 0; dente < 4; dente++) {
            float dx = centroX - raio * 0.44f + dente * raio * 0.29f;
            formas.triangle(
                    dx, y - raio * 0.14f,
                    dx + raio * 0.19f, y - raio * 0.14f,
                    dx + raio * 0.095f, y - raio * 0.42f);
        }

        // Olhos.
        formas.setColor(Paleta.TEXTO);
        formas.circle(centroX - raio * 0.38f, y + raio * 0.30f, raio * 0.26f, 20);
        formas.circle(centroX + raio * 0.38f, y + raio * 0.30f, raio * 0.26f, 20);
        formas.setColor(Paleta.PERIGO);
        formas.circle(centroX - raio * 0.34f, y + raio * 0.28f, raio * 0.13f, 16);
        formas.circle(centroX + raio * 0.42f, y + raio * 0.28f, raio * 0.13f, 16);
    }

    // -----------------------------------------------------------------------
    //  Ouro
    // -----------------------------------------------------------------------

    /** Gema dourada com facetas e raios de brilho pulsantes. */
    public static void ouro(ShapeRenderer formas, float centroX, float centroY,
            float lado, float tempo) {
        float escala = lado * 0.30f;
        float pulso = Desenho.pulsar(tempo, 2.6f);

        // Halo.
        formas.setColor(Paleta.comAlfa(Paleta.OURO, 0.10f + pulso * 0.10f));
        formas.circle(centroX, centroY, escala * (1.9f + pulso * 0.22f), 40);

        // Raios de brilho em cruz.
        float comprimento = escala * (1.22f + pulso * 0.30f);
        formas.setColor(Paleta.comAlfa(Paleta.OURO_CLARO, 0.35f + pulso * 0.30f));
        for (int raio = 0; raio < 4; raio++) {
            float angulo = raio * MathUtils.PI / 2f + tempo * 0.25f;
            float pontaX = centroX + MathUtils.cos(angulo) * comprimento;
            float pontaY = centroY + MathUtils.sin(angulo) * comprimento;
            float ladoX = -MathUtils.sin(angulo) * escala * 0.10f;
            float ladoY = MathUtils.cos(angulo) * escala * 0.10f;
            formas.triangle(pontaX, pontaY,
                    centroX + ladoX, centroY + ladoY,
                    centroX - ladoX, centroY - ladoY);
        }

        // Corpo da gema: mesa no topo, ombros laterais e ponta embaixo.
        float[] contorno = {
            centroX - escala * 0.52f, centroY + escala * 0.34f,
            centroX + escala * 0.52f, centroY + escala * 0.34f,
            centroX + escala * 0.84f, centroY + escala * 0.02f,
            centroX, centroY - escala * 0.92f,
            centroX - escala * 0.84f, centroY + escala * 0.02f
        };
        Desenho.leque(formas, centroX, centroY, contorno, Paleta.OURO);

        // Facetas claras e escuras dão volume à pedra.
        formas.setColor(Paleta.OURO_CLARO);
        formas.triangle(
                centroX - escala * 0.52f, centroY + escala * 0.34f,
                centroX + escala * 0.52f, centroY + escala * 0.34f,
                centroX, centroY + escala * 0.02f);
        formas.setColor(Paleta.OURO_ESCURO);
        formas.triangle(
                centroX + escala * 0.52f, centroY + escala * 0.34f,
                centroX + escala * 0.84f, centroY + escala * 0.02f,
                centroX, centroY - escala * 0.92f);
        formas.setColor(Paleta.comAlfa(Paleta.OURO_CLARO, 0.55f));
        formas.triangle(
                centroX - escala * 0.52f, centroY + escala * 0.34f,
                centroX - escala * 0.84f, centroY + escala * 0.02f,
                centroX, centroY - escala * 0.92f);
    }

    // -----------------------------------------------------------------------
    //  Casa inicial
    // -----------------------------------------------------------------------

    /** Portal verde que marca a casa de partida e de retorno. */
    public static void saida(ShapeRenderer formas, float centroX, float centroY,
            float lado, boolean destacada, float tempo) {
        float largura = lado * 0.30f;
        float altura = lado * 0.30f;
        float pulso = destacada ? Desenho.pulsar(tempo, 3.4f) : 0.25f;

        formas.setColor(Paleta.comAlfa(Paleta.INICIO, 0.10f + pulso * 0.14f));
        formas.circle(centroX, centroY, lado * 0.30f, 36);

        Color corDoPortal = Paleta.comAlfa(Paleta.INICIO, 0.55f + pulso * 0.35f);
        formas.setColor(corDoPortal);
        formas.rect(centroX - largura / 2f, centroY - altura * 0.72f,
                largura, altura);
        formas.circle(centroX, centroY + altura * 0.28f, largura / 2f, 26);

        formas.setColor(Paleta.PAINEL_INTERNO);
        float larguraInterna = largura * 0.58f;
        formas.rect(centroX - larguraInterna / 2f, centroY - altura * 0.72f,
                larguraInterna, altura * 0.92f);
        formas.circle(centroX, centroY + altura * 0.20f, larguraInterna / 2f, 22);
    }

    // -----------------------------------------------------------------------
    //  Sinais de percepção (selos pequenos dentro da casa já visitada)
    // -----------------------------------------------------------------------

    /** Três traços curvos, sugerindo a corrente de ar de um poço próximo. */
    public static void seloDeBrisa(ShapeRenderer formas, float centroX,
            float centroY, float tamanho, float alfa) {
        Color cor = Paleta.comAlfa(Paleta.BRISA, alfa);
        for (int traco = 0; traco < 3; traco++) {
            float y = centroY + (traco - 1) * tamanho * 0.34f;
            float comprimento = tamanho * (traco == 1 ? 1.0f : 0.72f);
            Desenho.linha(formas,
                    centroX - comprimento / 2f, y,
                    centroX + comprimento / 2f, y,
                    tamanho * 0.16f, cor);
        }
    }

    /** Três bolhas subindo, sugerindo o cheiro do Wumpus. */
    public static void seloDeFedor(ShapeRenderer formas, float centroX,
            float centroY, float tamanho, float alfa) {
        formas.setColor(Paleta.comAlfa(Paleta.FEDOR, alfa));
        formas.circle(centroX - tamanho * 0.34f, centroY - tamanho * 0.22f,
                tamanho * 0.22f, 14);
        formas.circle(centroX + tamanho * 0.02f, centroY + tamanho * 0.06f,
                tamanho * 0.30f, 16);
        formas.circle(centroX + tamanho * 0.40f, centroY + tamanho * 0.36f,
                tamanho * 0.18f, 12);
    }

    /** Estrela de quatro pontas usada como selo do brilho do ouro. */
    public static void seloDeBrilho(ShapeRenderer formas, float centroX,
            float centroY, float tamanho, float alfa) {
        Color cor = Paleta.comAlfa(Paleta.BRILHO, alfa);
        Desenho.losango(formas, centroX, centroY,
                tamanho * 0.26f, tamanho * 0.85f, cor);
        Desenho.losango(formas, centroX, centroY,
                tamanho * 0.85f, tamanho * 0.26f, cor);
    }

    // -----------------------------------------------------------------------
    //  Flecha
    // -----------------------------------------------------------------------

    /** Flecha em voo, com haste, ponta e penas. */
    public static void flecha(ShapeRenderer formas, float centroX, float centroY,
            Direcao direcao, float comprimento, Color cor) {
        float angulo = anguloDe(direcao) * MathUtils.degreesToRadians;
        float cosseno = MathUtils.cos(angulo);
        float seno = MathUtils.sin(angulo);
        float metade = comprimento / 2f;

        float traseiraX = centroX - cosseno * metade;
        float traseiraY = centroY - seno * metade;
        float frenteX = centroX + cosseno * metade;
        float frenteY = centroY + seno * metade;

        float espessura = comprimento * 0.10f;
        Desenho.linha(formas, traseiraX, traseiraY,
                frenteX - cosseno * comprimento * 0.22f,
                frenteY - seno * comprimento * 0.22f, espessura, cor);

        // Ponta.
        float baseX = frenteX - cosseno * comprimento * 0.26f;
        float baseY = frenteY - seno * comprimento * 0.26f;
        float meiaBase = comprimento * 0.15f;
        formas.setColor(cor);
        formas.triangle(frenteX, frenteY,
                baseX - seno * meiaBase, baseY + cosseno * meiaBase,
                baseX + seno * meiaBase, baseY - cosseno * meiaBase);

        // Penas.
        float penaX = traseiraX + cosseno * comprimento * 0.10f;
        float penaY = traseiraY + seno * comprimento * 0.10f;
        float meiaPena = comprimento * 0.13f;
        formas.triangle(traseiraX, traseiraY,
                penaX - seno * meiaPena, penaY + cosseno * meiaPena,
                penaX + seno * meiaPena, penaY - cosseno * meiaPena);
    }
}
package wumpusworld.grafico;

import com.badlogic.gdx.graphics.Color;
import com.badlogic.gdx.graphics.g2d.SpriteBatch;
import com.badlogic.gdx.graphics.glutils.ShapeRenderer;

import wumpusworld.nucleo.AgenteInteligente;
import wumpusworld.nucleo.Mundo;
import wumpusworld.nucleo.Partida;
import wumpusworld.nucleo.Percepcoes;
import wumpusworld.nucleo.Situacao;

/**
 * Painel com as informações da partida exigidas pelo enunciado:
 * posição atual, percepções, movimentos, pontuação e posse de ouro e flecha.
 *
 * <p>O layout é calculado uma única vez em {@link #definirArea(Area)} e
 * guardado em campos, para que a passagem de formas e a passagem de textos
 * usem exatamente as mesmas coordenadas.</p>
 */
public final class PainelStatus {

    private static final float MARGEM = 18f;

    private final Ativos ativos;

    private Area area = new Area(0f, 0f, 1f, 1f);
    private Area blocoPontuacao = area;
    private Area blocoObjetivo = area;
    private final Area[] azulejos = new Area[4];
    private final Area[] chipsDePercepcao = new Area[3];
    private final Area[] chipsDeInventario = new Area[2];
    private float baseDoTitulo;
    private float baseDoRotuloPercepcoes;

    public PainelStatus(Ativos ativos) {
        this.ativos = ativos;
    }

    public void definirArea(Area novaArea) {
        this.area = novaArea;

        float x = novaArea.x() + MARGEM;
        float largura = novaArea.largura() - MARGEM * 2f;
        float cursor = novaArea.topo() - MARGEM;

        baseDoTitulo = cursor - 4f;
        cursor -= 22f;

        cursor -= 8f;
        float alturaDoDestaque = 62f;
        float larguraDaPontuacao = largura * 0.46f;
        blocoPontuacao = new Area(x, cursor - alturaDoDestaque,
                larguraDaPontuacao, alturaDoDestaque);
        blocoObjetivo = new Area(x + larguraDaPontuacao + 12f,
                cursor - alturaDoDestaque,
                largura - larguraDaPontuacao - 12f, alturaDoDestaque);
        cursor -= alturaDoDestaque + 12f;

        float alturaDoAzulejo = 60f;
        float larguraDoAzulejo = (largura - 3f * 9f) / 4f;
        for (int indice = 0; indice < azulejos.length; indice++) {
            azulejos[indice] = new Area(
                    x + indice * (larguraDoAzulejo + 9f),
                    cursor - alturaDoAzulejo,
                    larguraDoAzulejo, alturaDoAzulejo);
        }
        cursor -= alturaDoAzulejo + 16f;

        baseDoRotuloPercepcoes = cursor - 2f;
        cursor -= 14f;

        float alturaDoChip = 36f;
        float larguraDoChip = (largura - 2f * 9f) / 3f;
        for (int indice = 0; indice < chipsDePercepcao.length; indice++) {
            chipsDePercepcao[indice] = new Area(
                    x + indice * (larguraDoChip + 9f),
                    cursor - alturaDoChip, larguraDoChip, alturaDoChip);
        }
        cursor -= alturaDoChip + 10f;

        float larguraDoInventario = (largura - 9f) / 2f;
        for (int indice = 0; indice < chipsDeInventario.length; indice++) {
            chipsDeInventario[indice] = new Area(
                    x + indice * (larguraDoInventario + 9f),
                    cursor - alturaDoChip, larguraDoInventario, alturaDoChip);
        }
    }

    // -----------------------------------------------------------------------
    //  Formas
    // -----------------------------------------------------------------------

    public void desenharFormas(ShapeRenderer formas, Partida partida,
            EstadoDaAnimacao animacao) {

        Desenho.sombra(formas, area, 16f, 0.45f);
        Desenho.painel(formas, area, 16f, Paleta.PAINEL, Paleta.BORDA, 1.5f);

        AgenteInteligente agente = partida.getAgente();
        Percepcoes percepcoes = partida.getPercepcoesAtuais();
        boolean vivo = agente.estaVivo();

        // Destaque da pontuação: verde quando positiva, vermelha quando negativa.
        Color corDaPontuacao = agente.getPontuacao() >= 0
                ? Paleta.SUCESSO : Paleta.PERIGO;
        Desenho.caixa(formas, blocoPontuacao, 12f, Paleta.PAINEL_INTERNO);
        Desenho.caixa(formas, blocoPontuacao.x(), blocoPontuacao.y(),
                4f, blocoPontuacao.altura(), 2f, corDaPontuacao);

        // Objetivo do momento.
        Color corDoObjetivo = corDaSituacao(partida);
        Desenho.caixa(formas, blocoObjetivo, 12f,
                Paleta.comAlfa(corDoObjetivo, 0.12f));
        Desenho.caixa(formas, blocoObjetivo.x(), blocoObjetivo.y(),
                4f, blocoObjetivo.altura(), 2f, corDoObjetivo);

        for (Area azulejo : azulejos) {
            Desenho.caixa(formas, azulejo, 10f, Paleta.PAINEL_INTERNO);
        }

        // Chips das percepções: acesos somente quando o sinal existe.
        desenharChipDePercepcao(formas, chipsDePercepcao[0],
                percepcoes.brisa() && vivo, Paleta.BRISA, animacao);
        desenharChipDePercepcao(formas, chipsDePercepcao[1],
                percepcoes.fedor() && vivo, Paleta.FEDOR, animacao);
        desenharChipDePercepcao(formas, chipsDePercepcao[2],
                percepcoes.brilho() && vivo, Paleta.BRILHO, animacao);

        // Selos dentro dos chips.
        float seloX = chipsDePercepcao[0].x() + 20f;
        float seloY = chipsDePercepcao[0].centroY();
        Icones.seloDeBrisa(formas, seloX, seloY, 6.5f,
                percepcoes.brisa() && vivo ? 1f : 0.30f);
        Icones.seloDeFedor(formas, chipsDePercepcao[1].x() + 20f, seloY, 8f,
                percepcoes.fedor() && vivo ? 1f : 0.30f);
        Icones.seloDeBrilho(formas, chipsDePercepcao[2].x() + 20f, seloY, 7.5f,
                percepcoes.brilho() && vivo ? 1f : 0.30f);

        // Inventário.
        desenharChipDeInventario(formas, chipsDeInventario[0],
                agente.possuiOuro(), Paleta.OURO);
        desenharChipDeInventario(formas, chipsDeInventario[1],
                agente.possuiFlecha(), Paleta.ALERTA);
    }

    private void desenharChipDePercepcao(ShapeRenderer formas, Area chip,
            boolean ativo, Color cor, EstadoDaAnimacao animacao) {
        if (ativo) {
            float pulso = Desenho.pulsar(animacao.tempo(), 4.2f);
            Desenho.painel(formas, chip, 10f,
                    Paleta.comAlfa(cor, 0.16f + pulso * 0.06f),
                    Paleta.comAlfa(cor, 0.55f + pulso * 0.35f), 1.4f);
        } else {
            Desenho.caixa(formas, chip, 10f, Paleta.PAINEL_INTERNO);
        }
    }

    private void desenharChipDeInventario(ShapeRenderer formas, Area chip,
            boolean possui, Color cor) {
        if (possui) {
            Desenho.painel(formas, chip, 10f,
                    Paleta.comAlfa(cor, 0.16f), Paleta.comAlfa(cor, 0.6f), 1.4f);
        } else {
            Desenho.caixa(formas, chip, 10f, Paleta.PAINEL_INTERNO);
        }

        // Pequeno indicador redondo à esquerda do rótulo.
        formas.setColor(possui ? cor : Paleta.comAlfa(Paleta.TEXTO_FRACO, 0.6f));
        formas.circle(chip.x() + 20f, chip.centroY(), 5.5f, 18);
    }

    // -----------------------------------------------------------------------
    //  Textos
    // -----------------------------------------------------------------------

    public void desenharTextos(SpriteBatch lote, Partida partida) {
        AgenteInteligente agente = partida.getAgente();
        Percepcoes percepcoes = partida.getPercepcoesAtuais();
        Mundo mundo = partida.getMundo();
        boolean vivo = agente.estaVivo();

        Desenho.texto(lote, ativos.fonteSecao, "INFORMAÇÕES DA PARTIDA",
                area.x() + MARGEM + 2f, baseDoTitulo, Paleta.TEXTO_SUAVE);

        // Pontuação.
        Desenho.texto(lote, ativos.fonteMiuda, "PONTUAÇÃO",
                blocoPontuacao.x() + 16f, blocoPontuacao.topo() - 9f,
                Paleta.TEXTO_FRACO);
        Desenho.texto(lote, ativos.fonteTitulo,
                String.valueOf(agente.getPontuacao()),
                blocoPontuacao.x() + 16f, blocoPontuacao.topo() - 26f,
                agente.getPontuacao() >= 0 ? Paleta.SUCESSO : Paleta.PERIGO);

        // Objetivo.
        Color corDoObjetivo = corDaSituacao(partida);
        Desenho.texto(lote, ativos.fonteMiuda, "SITUAÇÃO",
                blocoObjetivo.x() + 16f, blocoObjetivo.topo() - 9f,
                Paleta.TEXTO_FRACO);
        Desenho.texto(lote, ativos.fonteTextoForte, tituloDaSituacao(partida),
                blocoObjetivo.x() + 16f, blocoObjetivo.topo() - 26f,
                corDoObjetivo);
        Desenho.texto(lote, ativos.fontePequena, detalheDaSituacao(partida),
                blocoObjetivo.x() + 16f, blocoObjetivo.topo() - 44f,
                Paleta.TEXTO_FRACO);

        // Azulejos numéricos.
        escreverAzulejo(lote, azulejos[0], "POSIÇÃO",
                agente.getPosicao().toString(), Paleta.AGENTE);
        escreverAzulejo(lote, azulejos[1], "MOVIMENTOS",
                String.valueOf(agente.getQuantidadeDeMovimentos()), Paleta.TEXTO);
        escreverAzulejo(lote, azulejos[2], "TURNO",
                String.valueOf(partida.getTurno()), Paleta.TEXTO);
        escreverAzulejo(lote, azulejos[3], "CASAS VISTAS",
                mundo.quantidadeDeCasasVisitadas() + "/"
                + (Mundo.TAMANHO * Mundo.TAMANHO), Paleta.TEXTO);

        // Percepções.
        Desenho.texto(lote, ativos.fonteMiuda, "PERCEPÇÕES NA CASA ATUAL",
                area.x() + MARGEM + 2f, baseDoRotuloPercepcoes, Paleta.TEXTO_FRACO);

        escreverChip(lote, chipsDePercepcao[0], "BRISA",
                percepcoes.brisa() && vivo, Paleta.BRISA);
        escreverChip(lote, chipsDePercepcao[1], "FEDOR",
                percepcoes.fedor() && vivo, Paleta.FEDOR);
        escreverChip(lote, chipsDePercepcao[2], "BRILHO",
                percepcoes.brilho() && vivo, Paleta.BRILHO);

        // Inventário.
        escreverChip(lote, chipsDeInventario[0],
                agente.possuiOuro() ? "OURO: RECOLHIDO" : "OURO: NÃO ENCONTRADO",
                agente.possuiOuro(), Paleta.OURO);
        escreverChip(lote, chipsDeInventario[1],
                agente.possuiFlecha() ? "FLECHA: DISPONÍVEL" : "FLECHA: USADA",
                agente.possuiFlecha(), Paleta.ALERTA);
    }

    private void escreverAzulejo(SpriteBatch lote, Area azulejo, String rotulo,
            String valor, Color corDoValor) {
        Desenho.textoCentralizado(lote, ativos.fonteMiuda, rotulo,
                azulejo.centroX(), azulejo.topo() - 9f, Paleta.TEXTO_FRACO);
        Desenho.textoCentralizado(lote, ativos.fonteValor, valor,
                azulejo.centroX(), azulejo.topo() - 26f, corDoValor);
    }

    private void escreverChip(SpriteBatch lote, Area chip, String rotulo,
            boolean ativo, Color cor) {
        Desenho.texto(lote, ativos.fonteTextoForte, rotulo,
                chip.x() + 34f,
                chip.centroY() + ativos.fonteTextoForte.getCapHeight() / 2f,
                ativo ? cor : Paleta.TEXTO_FRACO);
    }

    // -----------------------------------------------------------------------

    private static Color corDaSituacao(Partida partida) {
        Situacao situacao = partida.getSituacao();
        if (situacao == Situacao.EM_ANDAMENTO) {
            return partida.getAgente().possuiOuro() ? Paleta.OURO : Paleta.AGENTE;
        }
        return switch (situacao) {
            case VITORIA -> Paleta.SUCESSO;
            case MORTE -> Paleta.PERIGO;
            case LIMITE_ATINGIDO -> Paleta.ALERTA;
            default -> Paleta.NEUTRO;
        };
    }

    private static String tituloDaSituacao(Partida partida) {
        if (partida.getSituacao() != Situacao.EM_ANDAMENTO) {
            return partida.getSituacao().getTitulo();
        }
        return partida.getAgente().possuiOuro()
                ? "RETORNANDO COM O OURO" : "EXPLORANDO A CAVERNA";
    }

    private static String detalheDaSituacao(Partida partida) {
        if (partida.getSituacao() != Situacao.EM_ANDAMENTO) {
            return partida.getSituacao().getDescricao();
        }
        return partida.getAgente().possuiOuro()
                ? "Refazendo o caminho seguro até [0][0]."
                : "Procurando o ouro e evitando os perigos.";
    }
}
package wumpusworld.grafico;

import com.badlogic.gdx.graphics.Color;
import com.badlogic.gdx.graphics.g2d.SpriteBatch;
import com.badlogic.gdx.graphics.glutils.ShapeRenderer;
import com.badlogic.gdx.math.MathUtils;

import wumpusworld.nucleo.AgenteInteligente;
import wumpusworld.nucleo.Mundo;
import wumpusworld.nucleo.Partida;
import wumpusworld.nucleo.Situacao;

/**
 * Cartão de encerramento sobreposto à tela.
 *
 * <p>Mostra com clareza o desfecho — morte, vitória com o ouro ou limite de
 * exploração — junto do resumo numérico da partida. Enquanto ele aparece, o
 * mapa já está revelado no tabuleiro, atendendo ao pedido do enunciado de
 * exibir o mapa completo ao final.</p>
 */
public final class CamadaResultado {

    private final Ativos ativos;

    private float larguraDaTela;
    private float alturaDaTela;
    private Area cartao = new Area(0f, 0f, 660f, 300f);
    private float progresso;

    public CamadaResultado(Ativos ativos) {
        this.ativos = ativos;
    }

    /**
     * @param alvo    onde o cartão deve aparecer; fica sobre a coluna lateral
     *                para que o mapa revelado continue inteiramente visível
     * @param largura largura da tela virtual, usada pelo véu de escurecimento
     * @param altura  altura da tela virtual
     */
    public void definirArea(Area alvo, float largura, float altura) {
        this.cartao = alvo;
        this.larguraDaTela = largura;
        this.alturaDaTela = altura;
    }

    /** Reinicia a animação de entrada do cartão. */
    public void reiniciar() {
        progresso = 0f;
    }

    public void atualizar(float delta, boolean visivel) {
        if (visivel) {
            progresso = Math.min(1f, progresso + delta * 2.4f);
        } else {
            progresso = 0f;
        }
    }

    public boolean estaVisivel() {
        return progresso > 0f;
    }

    public void desenharFormas(ShapeRenderer formas, Partida partida,
            float tempo) {
        if (progresso <= 0f) {
            return;
        }

        float suave = Desenho.suavizar(progresso);
        Color cor = corDoResultado(partida.getSituacao());

        // Escurece o restante da tela sem apagá-lo por completo.
        formas.setColor(0f, 0f, 0f, 0.30f * suave);
        formas.rect(0f, 0f, larguraDaTela, alturaDaTela);

        // O cartão cresce um pouco ao entrar.
        float escala = 0.94f + 0.06f * suave;
        Area alvo = escalar(cartao, escala);

        Desenho.sombra(formas, alvo, 20f, 0.8f * suave);
        Desenho.painel(formas, alvo, 20f,
                Paleta.comAlfa(Paleta.PAINEL, suave),
                Paleta.comAlfa(cor, 0.65f * suave), 2f);

        // Faixa colorida no topo do cartão.
        Desenho.caixa(formas, alvo.x() + 20f, alvo.topo() - 6f,
                alvo.largura() - 40f, 4f, 2f, Paleta.comAlfa(cor, suave));

        // Emblema do desfecho.
        float emblemaX = alvo.x() + 78f;
        float emblemaY = alvo.topo() - 80f;
        formas.setColor(Paleta.comAlfa(cor, 0.12f * suave));
        formas.circle(emblemaX, emblemaY, 42f, 40);
        Desenho.anel(formas, emblemaX, emblemaY, 40f, 42f,
                Paleta.comAlfa(cor, 0.5f * suave), 48);

        switch (partida.getSituacao()) {
            case VITORIA -> Icones.ouro(formas, emblemaX, emblemaY, 118f, tempo);
            case MORTE -> Icones.caveira(formas, emblemaX, emblemaY, 150f);
            default -> relogio(formas, emblemaX, emblemaY, 30f,
                    Paleta.comAlfa(cor, suave), tempo);
        }

        // Área dos números.
        Desenho.caixa(formas, alvo.x() + 26f, alvo.y() + 56f,
                alvo.largura() - 52f, 68f, 12f,
                Paleta.comAlfa(Paleta.PAINEL_INTERNO, suave));
    }

    /** Relógio simples usado quando a partida acaba por limite de movimentos. */
    private void relogio(ShapeRenderer formas, float centroX, float centroY,
            float raio, Color cor, float tempo) {
        Desenho.anel(formas, centroX, centroY, raio * 0.82f, raio, cor, 44);
        float angulo = tempo * 1.4f;
        Desenho.linha(formas, centroX, centroY,
                centroX + MathUtils.cos(angulo) * raio * 0.55f,
                centroY + MathUtils.sin(angulo) * raio * 0.55f, 4f, cor);
        Desenho.linha(formas, centroX, centroY,
                centroX + MathUtils.cos(angulo * 0.35f) * raio * 0.34f,
                centroY + MathUtils.sin(angulo * 0.35f) * raio * 0.34f, 4f, cor);
    }

    public void desenharTextos(SpriteBatch lote, Partida partida) {
        if (progresso <= 0f) {
            return;
        }

        float suave = Desenho.suavizar(progresso);
        Situacao situacao = partida.getSituacao();
        AgenteInteligente agente = partida.getAgente();
        Color cor = Paleta.comAlfa(corDoResultado(situacao), suave);
        Area alvo = escalar(cartao, 0.94f + 0.06f * suave);

        float textoX = alvo.x() + 140f;
        Desenho.texto(lote, ativos.fonteBanner, situacao.getTitulo(),
                textoX, alvo.topo() - 46f, cor);
        Desenho.texto(lote, ativos.fonteTexto, situacao.getDescricao(),
                textoX, alvo.topo() - 104f,
                Paleta.comAlfa(Paleta.TEXTO_SUAVE, suave));

        // Quatro números que resumem a partida.
        float larguraDaColuna = (alvo.largura() - 52f) / 4f;
        float baseDosRotulos = alvo.y() + 108f;
        float baseDosValores = alvo.y() + 92f;

        escreverResumo(lote, alvo.x() + 26f + larguraDaColuna * 0.5f,
                baseDosRotulos, baseDosValores, "PONTUAÇÃO FINAL",
                String.valueOf(agente.getPontuacao()),
                Paleta.comAlfa(agente.getPontuacao() >= 0
                        ? Paleta.SUCESSO : Paleta.PERIGO, suave), suave);
        escreverResumo(lote, alvo.x() + 26f + larguraDaColuna * 1.5f,
                baseDosRotulos, baseDosValores, "MOVIMENTOS",
                String.valueOf(agente.getQuantidadeDeMovimentos()),
                Paleta.comAlfa(Paleta.TEXTO, suave), suave);
        escreverResumo(lote, alvo.x() + 26f + larguraDaColuna * 2.5f,
                baseDosRotulos, baseDosValores, "CASAS VISITADAS",
                partida.getMundo().quantidadeDeCasasVisitadas() + "/"
                + (Mundo.TAMANHO * Mundo.TAMANHO),
                Paleta.comAlfa(Paleta.TEXTO, suave), suave);
        escreverResumo(lote, alvo.x() + 26f + larguraDaColuna * 3.5f,
                baseDosRotulos, baseDosValores, "OURO",
                agente.possuiOuro() ? "SIM" : "NÃO",
                Paleta.comAlfa(agente.possuiOuro()
                        ? Paleta.OURO : Paleta.TEXTO_FRACO, suave), suave);

        Desenho.textoCentralizado(lote, ativos.fonteMiuda,
                "R sorteia um novo mapa   ·   ESC encerra",
                alvo.centroX(), alvo.y() + 36f,
                Paleta.comAlfa(Paleta.TEXTO_FRACO, suave));
    }

    private void escreverResumo(SpriteBatch lote, float centroX,
            float baseDoRotulo, float baseDoValor, String rotulo, String valor,
            Color corDoValor, float suave) {
        Desenho.textoCentralizado(lote, ativos.fonteMiuda, rotulo,
                centroX, baseDoRotulo, Paleta.comAlfa(Paleta.TEXTO_FRACO, suave));
        Desenho.textoCentralizado(lote, ativos.fonteValor, valor,
                centroX, baseDoValor, corDoValor);
    }

    private static Area escalar(Area base, float escala) {
        float largura = base.largura() * escala;
        float altura = base.altura() * escala;
        return new Area(base.centroX() - largura / 2f,
                base.centroY() - altura / 2f, largura, altura);
    }

    private static Color corDoResultado(Situacao situacao) {
        return switch (situacao) {
            case VITORIA -> Paleta.SUCESSO;
            case MORTE -> Paleta.PERIGO;
            case LIMITE_ATINGIDO -> Paleta.ALERTA;
            default -> Paleta.NEUTRO;
        };
    }
}
        Gdx.gl.glEnable(GL20.GL_BLEND);
        // Cor: composição normal. Alfa: a função separada mantém o quadro
        // opaco, o que evita véus translúcidos "furarem" a imagem final.
        Gdx.gl.glBlendFuncSeparate(
                GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA,
                GL20.GL_ONE, GL20.GL_ONE_MINUS_SRC_ALPHA);
    }

    private void posicionarCamera(float deslocamentoX, float deslocamentoY) {
        camera.position.set(LARGURA_VIRTUAL / 2f + deslocamentoX,
                ALTURA_VIRTUAL / 2f + deslocamentoY, 0f);
        camera.update();
    }

    /** Degradê da caverna, poeira em suspensão e vinheta nas bordas. */
    private void desenharFundo() {
        Desenho.degradeVertical(formas, 0f, 0f, LARGURA_VIRTUAL, ALTURA_VIRTUAL,
                Paleta.FUNDO_BAIXO, Paleta.FUNDO_ALTO);

        for (int indice = 0; indice < poeiraX.length; indice++) {
            formas.setColor(Paleta.comAlfa(Paleta.AGENTE_BRILHO,
                    poeiraAlfa[indice]));
            formas.circle(poeiraX[indice], poeiraY[indice],
                    poeiraRaio[indice], 10);
        }

        Color opaco = new Color(0f, 0f, 0f, 0.55f);
        Color transparente = new Color(0f, 0f, 0f, 0f);
        float faixa = 130f;
        formas.rect(0f, 0f, LARGURA_VIRTUAL, faixa,
                opaco, opaco, transparente, transparente);
        formas.rect(0f, ALTURA_VIRTUAL - faixa, LARGURA_VIRTUAL, faixa,
                transparente, transparente, opaco, opaco);
        formas.rect(0f, 0f, faixa, ALTURA_VIRTUAL,
                opaco, transparente, transparente, opaco);
        formas.rect(LARGURA_VIRTUAL - faixa, 0f, faixa, ALTURA_VIRTUAL,
                transparente, opaco, opaco, transparente);
    }

    @Override
    public void resize(int largura, int altura) {
        viewport.update(largura, altura, true);
    }

    @Override
    public void hide() {
        Gdx.input.setInputProcessor(null);
    }

    /** Situação atual, exposta para testes e para a barra de título da janela. */
    public Situacao getSituacao() {
        return partida.getSituacao();
    }
}

